# Function to check if a permutation is valid
def is_valid(perm):
    # Check rows and columns
    for i in range(10):
        row = [perm[i*10+j] for j in range(10)]
        col = [perm[j*10+i] for j in range(10)]
        if len(set(row)) != 10 or len(set(col)) != 10:
            return False
    return True

# Find a valid permutation
for p in permutations(range(10)):
    perm = clues[:]
    for i in range(100):
        if perm[i] == -1:
            perm[i] = p[i%10]
    if is_valid(perm):
        print(perm)
        break
else:
    print("UNSATISFIABLE")
